"""Exception hierarchy for microvm."""


class MicroVMError(Exception):
    """Base exception for all microvm errors."""


class LexError(MicroVMError):
    """Lexer error with a zero-based character offset."""

    def __init__(self, message: str, offset: int) -> None:
        super().__init__(message)
        self.offset: int = offset


class ParseError(MicroVMError):
    """Parser error with a zero-based character offset."""

    def __init__(self, message: str, offset: int) -> None:
        super().__init__(message)
        self.offset: int = offset


class CompileError(MicroVMError):
    """Compiler error."""


class SerializationError(MicroVMError):
    """Binary format serialization or deserialization error."""


class VMRuntimeError(MicroVMError):
    """Runtime execution error."""


class StepLimitError(VMRuntimeError):
    """Execution exceeded the step limit."""

"""Bytecode opcodes and numeric mappings for microvm."""

OPCODES: tuple[str, ...] = (
    "CONST", "LOAD", "STORE", "ADD", "SUB", "MUL", "DIV", "MOD", "NEG", "NOT",
    "EQ", "NE", "LT", "LE", "GT", "GE", "JUMP", "JUMP_IF_FALSE", "PRINT", "POP", "HALT",
)

OPCODE_NUMBERS: dict[str, int] = {name: index + 1 for index, name in enumerate(OPCODES)}

"""Lexer for microvm."""

import dataclasses
from microvm.errors import LexError

KEYWORDS: frozenset[str] = frozenset({
    "let", "print", "if", "else", "while", "true", "false", "and", "or", "not"
})

TWO_CHAR_OPS: tuple[str, ...] = ("==", "!=", "<=", ">=")
ONE_CHAR_OPS: tuple[str, ...] = ("+", "-", "*", "/", "%", "(", ")", "{", "}", ";", "=", "<", ">")


@dataclasses.dataclass(frozen=True)
class Token:
    kind: str      # "INT" | "FLOAT" | "STRING" | "IDENT" | "KEYWORD" | "OP"
    text: str      # the source lexeme (for STRING: the decoded value)
    value: object  # INT -> int, FLOAT -> float, STRING -> decoded str, else same as text
    offset: int    # zero-based character offset of the first character


def _lex_string(src: str, start: int) -> tuple[Token, int]:
    i = start + 1
    chars: list[str] = []
    n = len(src)
    while i < n:
        c = src[i]
        if c == '"':
            decoded = "".join(chars)
            return Token("STRING", decoded, decoded, start), i + 1
        if c in "\r\n":
            raise LexError("Literal newline in string literal", i)
        if c == "\\":
            i += 1
            if i >= n:
                raise LexError("Unterminated escape sequence", i - 1)
            esc = src[i]
            if esc == "n":
                chars.append("\n")
            elif esc == "t":
                chars.append("\t")
            elif esc == '"':
                chars.append('"')
            elif esc == "\\":
                chars.append("\\")
            else:
                raise LexError(f"Invalid escape sequence '\\{esc}'", i - 1)
            i += 1
        else:
            chars.append(c)
            i += 1
    raise LexError("Unterminated string literal", start)


def _lex_float_exponent(src: str, i: int, n: int) -> int:
    if i < n and src[i] in "eE":
        exp_start = i
        i += 1
        if i < n and src[i] in "+-":
            i += 1
        if i >= n or not src[i].isdigit():
            raise LexError("Invalid float exponent", exp_start)
        while i < n and src[i].isdigit():
            i += 1
    return i


def _lex_number(src: str, start: int) -> tuple[Token, int]:
    i = start
    n = len(src)
    while i < n and src[i].isdigit():
        i += 1
    if i < n and src[i] == ".":
        dot_pos = i
        i += 1
        if i >= n or not src[i].isdigit():
            raise LexError("Float requires digits after decimal point", dot_pos)
        while i < n and src[i].isdigit():
            i += 1
        i = _lex_float_exponent(src, i, n)
        if i < n and (src[i].isalpha() or src[i] == "_"):
            raise LexError("Invalid character after number", i)
        lexeme = src[start:i]
        return Token("FLOAT", lexeme, float(lexeme), start), i
    if i < n and (src[i].isalpha() or src[i] == "_"):
        raise LexError("Invalid character after number", i)
    lexeme = src[start:i]
    return Token("INT", lexeme, int(lexeme), start), i


def _lex_ident(src: str, start: int) -> tuple[Token, int]:
    i = start
    n = len(src)
    while i < n and (src[i].isalnum() or src[i] == "_"):
        i += 1
    lexeme = src[start:i]
    kind = "KEYWORD" if lexeme in KEYWORDS else "IDENT"
    return Token(kind, lexeme, lexeme, start), i


def tokenize(src: str) -> list[Token]:
    tokens: list[Token] = []
    i = 0
    n = len(src)
    while i < n:
        c = src[i]
        if c.isspace():
            i += 1
            continue
        if c == "/" and i + 1 < n and src[i + 1] == "/":
            i += 2
            while i < n and src[i] != "\n":
                i += 1
            continue
        if c == '"':
            tok, i = _lex_string(src, i)
            tokens.append(tok)
            continue
        if c.isdigit():
            tok, i = _lex_number(src, i)
            tokens.append(tok)
            continue
        if c.isalpha() or c == "_":
            tok, i = _lex_ident(src, i)
            tokens.append(tok)
            continue
        matched_op = False
        if i + 1 < n and src[i : i + 2] in TWO_CHAR_OPS:
            tokens.append(Token("OP", src[i : i + 2], src[i : i + 2], i))
            i += 2
            matched_op = True
        elif c in ONE_CHAR_OPS:
            tokens.append(Token("OP", c, c, i))
            i += 1
            matched_op = True
        if not matched_op:
            raise LexError(f"Unexpected character {c!r}", i)
    return tokens

"""Parser and AST definition for microvm."""

import dataclasses
from microvm.errors import ParseError
from microvm.lexer import Token, tokenize


@dataclasses.dataclass(frozen=True)
class Literal:
    value: int | float | str | bool
    offset: int


@dataclasses.dataclass(frozen=True)
class Var:
    name: str
    offset: int


@dataclasses.dataclass(frozen=True)
class UnaryOp:
    op: str
    expr: object
    offset: int


@dataclasses.dataclass(frozen=True)
class BinaryOp:
    op: str
    left: object
    right: object
    offset: int


@dataclasses.dataclass(frozen=True)
class LetStmt:
    name: str
    expr: object
    offset: int


@dataclasses.dataclass(frozen=True)
class AssignStmt:
    name: str
    expr: object
    offset: int


@dataclasses.dataclass(frozen=True)
class PrintStmt:
    expr: object
    offset: int


@dataclasses.dataclass(frozen=True)
class IfStmt:
    cond: object
    then_block: list[object]
    else_branch: object  # list[object] | IfStmt | None
    offset: int


@dataclasses.dataclass(frozen=True)
class WhileStmt:
    cond: object
    body: list[object]
    offset: int


@dataclasses.dataclass(frozen=True)
class BlockStmt:
    stmts: list[object]
    offset: int


@dataclasses.dataclass(frozen=True)
class ProgramNode:
    stmts: list[object]


class Parser:
    def __init__(self, src: str, tokens: list[Token]) -> None:
        self.src: str = src
        self.tokens: list[Token] = tokens
        self.pos: int = 0

    def peek(self) -> Token | None:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def match(self, kind: str, text: str | None = None) -> bool:
        tok = self.peek()
        if not tok or tok.kind != kind:
            return False
        if text is not None and tok.text != text:
            return False
        return True

    def consume(self, kind: str, text: str | None = None) -> Token:
        tok = self.peek()
        if not tok:
            raise ParseError("Unexpected end of input", len(self.src))
        if tok.kind != kind or (text is not None and tok.text != text):
            expected = f"{kind} '{text}'" if text else kind
            raise ParseError(f"Expected {expected}, got {tok.kind} '{tok.text}'", tok.offset)
        self.pos += 1
        return tok

    def parse_statement(self) -> object:
        tok = self.peek()
        if not tok:
            raise ParseError("Unexpected end of input", len(self.src))
        if tok.kind == "KEYWORD":
            if tok.text == "let":
                return self.parse_let()
            if tok.text == "print":
                return self.parse_print()
            if tok.text == "if":
                return self.parse_if()
            if tok.text == "while":
                return self.parse_while()
        if tok.kind == "OP" and tok.text == "{":
            return self.parse_block_stmt()
        if tok.kind == "IDENT":
            return self.parse_assign()
        raise ParseError(f"Unexpected token {tok.text!r}", tok.offset)

    def parse_let(self) -> LetStmt:
        start_tok = self.consume("KEYWORD", "let")
        name_tok = self.consume("IDENT")
        self.consume("OP", "=")
        expr = self.parse_expr()
        self.consume("OP", ";")
        return LetStmt(name=name_tok.text, expr=expr, offset=start_tok.offset)

    def parse_assign(self) -> AssignStmt:
        name_tok = self.consume("IDENT")
        self.consume("OP", "=")
        expr = self.parse_expr()
        self.consume("OP", ";")
        return AssignStmt(name=name_tok.text, expr=expr, offset=name_tok.offset)

    def parse_print(self) -> PrintStmt:
        start_tok = self.consume("KEYWORD", "print")
        expr = self.parse_expr()
        self.consume("OP", ";")
        return PrintStmt(expr=expr, offset=start_tok.offset)

    def parse_block_stmts(self) -> list[object]:
        self.consume("OP", "{")
        stmts: list[object] = []
        while True:
            tok = self.peek()
            if not tok:
                raise ParseError("Unclosed block, expected '}'", len(self.src))
            if tok.kind == "OP" and tok.text == "}":
                self.consume("OP", "}")
                break
            stmts.append(self.parse_statement())
        return stmts

    def parse_block_stmt(self) -> BlockStmt:
        tok = self.peek()
        offset = tok.offset if tok else len(self.src)
        stmts = self.parse_block_stmts()
        return BlockStmt(stmts=stmts, offset=offset)

    def parse_if(self) -> IfStmt:
        start_tok = self.consume("KEYWORD", "if")
        self.consume("OP", "(")
        cond = self.parse_expr()
        self.consume("OP", ")")
        then_block = self.parse_block_stmts()
        else_branch: object = None
        if self.match("KEYWORD", "else"):
            self.consume("KEYWORD", "else")
            if self.match("KEYWORD", "if"):
                else_branch = self.parse_if()
            elif self.match("OP", "{"):
                else_branch = self.parse_block_stmts()
            else:
                tok = self.peek()
                offset = tok.offset if tok else len(self.src)
                raise ParseError("Expected '{' or 'if' after 'else'", offset)
        return IfStmt(cond=cond, then_block=then_block, else_branch=else_branch, offset=start_tok.offset)

    def parse_while(self) -> WhileStmt:
        start_tok = self.consume("KEYWORD", "while")
        self.consume("OP", "(")
        cond = self.parse_expr()
        self.consume("OP", ")")
        body = self.parse_block_stmts()
        return WhileStmt(cond=cond, body=body, offset=start_tok.offset)

    def parse_expr(self) -> object:
        return self.parse_or()

    def parse_or(self) -> object:
        node = self.parse_and()
        while self.match("KEYWORD", "or"):
            op = self.consume("KEYWORD", "or")
            right = self.parse_and()
            node = BinaryOp("or", node, right, op.offset)
        return node

    def parse_and(self) -> object:
        node = self.parse_not()
        while self.match("KEYWORD", "and"):
            op = self.consume("KEYWORD", "and")
            right = self.parse_not()
            node = BinaryOp("and", node, right, op.offset)
        return node

    def parse_not(self) -> object:
        if self.match("KEYWORD", "not"):
            op = self.consume("KEYWORD", "not")
            operand = self.parse_not()
            return UnaryOp("not", operand, op.offset)
        return self.parse_comparison()

    def parse_comparison(self) -> object:
        node = self.parse_additive()
        cmp_ops = ("==", "!=", "<", "<=", ">", ">=")
        tok = self.peek()
        if tok and tok.kind == "OP" and tok.text in cmp_ops:
            op = self.consume("OP")
            right = self.parse_additive()
            node = BinaryOp(op.text, node, right, op.offset)
            next_tok = self.peek()
            if next_tok and next_tok.kind == "OP" and next_tok.text in cmp_ops:
                raise ParseError("Comparison operators are not associative", next_tok.offset)
        return node

    def parse_additive(self) -> object:
        node = self.parse_multiplicative()
        while True:
            tok = self.peek()
            if tok and tok.kind == "OP" and tok.text in ("+", "-"):
                op = self.consume("OP")
                right = self.parse_multiplicative()
                node = BinaryOp(op.text, node, right, op.offset)
            else:
                break
        return node

    def parse_multiplicative(self) -> object:
        node = self.parse_unary()
        while True:
            tok = self.peek()
            if tok and tok.kind == "OP" and tok.text in ("*", "/", "%"):
                op = self.consume("OP")
                right = self.parse_unary()
                node = BinaryOp(op.text, node, right, op.offset)
            else:
                break
        return node

    def parse_unary(self) -> object:
        tok = self.peek()
        if tok and tok.kind == "OP" and tok.text == "-":
            op = self.consume("OP", "-")
            operand = self.parse_unary()
            return UnaryOp("-", operand, op.offset)
        return self.parse_primary()

    def parse_primary(self) -> object:
        tok = self.peek()
        if not tok:
            raise ParseError("Expected expression, got end of input", len(self.src))
        if tok.kind in ("INT", "FLOAT", "STRING"):
            self.consume(tok.kind)
            return Literal(tok.value, tok.offset)
        if tok.kind == "KEYWORD" and tok.text == "true":
            self.consume("KEYWORD", "true")
            return Literal(True, tok.offset)
        if tok.kind == "KEYWORD" and tok.text == "false":
            self.consume("KEYWORD", "false")
            return Literal(False, tok.offset)
        if tok.kind == "IDENT":
            self.consume("IDENT")
            return Var(tok.text, tok.offset)
        if tok.kind == "OP" and tok.text == "(":
            self.consume("OP", "(")
            expr = self.parse_expr()
            self.consume("OP", ")")
            return expr
        raise ParseError(f"Unexpected token in expression: {tok.text!r}", tok.offset)


def parse(src: str) -> object:
    tokens = tokenize(src)
    parser = Parser(src, tokens)
    stmts: list[object] = []
    while parser.peek() is not None:
        stmts.append(parser.parse_statement())
    return ProgramNode(stmts=stmts)

"""AST constant folder for microvm."""

from microvm.parser import (
    AssignStmt,
    BinaryOp,
    BlockStmt,
    IfStmt,
    LetStmt,
    Literal,
    PrintStmt,
    ProgramNode,
    UnaryOp,
    WhileStmt,
)


def is_num(v: object) -> bool:
    return (type(v) in (int, float)) and (type(v) is not bool)


def vm_equals(a: object, b: object) -> bool:
    if type(a) is bool or type(b) is bool:
        return (type(a) is bool and type(b) is bool) and (a is b)
    if (type(a) in (int, float)) and (type(b) in (int, float)):
        return a == b
    if type(a) is str and type(b) is str:
        return a == b
    return False


def _fold_arithmetic(op: str, lv: object, rv: object) -> tuple[bool, object]:
    if op == "+":
        if type(lv) is str and type(rv) is str:
            return True, lv + rv
        if is_num(lv) and is_num(rv):
            res = lv + rv  # type: ignore[operator]
            return True, int(res) if (type(lv) is int and type(rv) is int) else float(res)
    elif op in ("-", "*"):
        if is_num(lv) and is_num(rv):
            res = (lv - rv) if op == "-" else (lv * rv)  # type: ignore[operator]
            return True, int(res) if (type(lv) is int and type(rv) is int) else float(res)
    elif op == "/":
        if is_num(lv) and is_num(rv) and rv != 0:
            return True, float(lv) / float(rv)  # type: ignore[arg-type]
    elif op == "%":
        if type(lv) is int and type(rv) is int and type(lv) is not bool and type(rv) is not bool:
            if rv != 0:
                return True, lv % rv
    return False, None


def _fold_comparison(op: str, lv: object, rv: object) -> tuple[bool, object]:
    if op == "==":
        return True, vm_equals(lv, rv)
    if op == "!=":
        return True, not vm_equals(lv, rv)
    if is_num(lv) and is_num(rv):
        if op == "<":
            return True, lv < rv  # type: ignore[operator]
        if op == "<=":
            return True, lv <= rv  # type: ignore[operator]
        if op == ">":
            return True, lv > rv  # type: ignore[operator]
        if op == ">=":
            return True, lv >= rv  # type: ignore[operator]
    if type(lv) is str and type(rv) is str:
        if op == "<":
            return True, lv < rv
        if op == "<=":
            return True, lv <= rv
        if op == ">":
            return True, lv > rv
        if op == ">=":
            return True, lv >= rv
    return False, None


def _fold_binary_op(node: BinaryOp) -> object:
    left = fold_constants(node.left)
    right = fold_constants(node.right)
    if node.op == "and":
        if isinstance(left, Literal) and type(left.value) is bool:
            if isinstance(right, Literal) and type(right.value) is bool:
                return Literal(left.value and right.value, node.offset)
            if left.value is False:
                return Literal(False, node.offset)
        return BinaryOp("and", left, right, node.offset)
    if node.op == "or":
        if isinstance(left, Literal) and type(left.value) is bool:
            if isinstance(right, Literal) and type(right.value) is bool:
                return Literal(left.value or right.value, node.offset)
            if left.value is True:
                return Literal(True, node.offset)
        return BinaryOp("or", left, right, node.offset)
    if isinstance(left, Literal) and isinstance(right, Literal):
        ok, val = _fold_arithmetic(node.op, left.value, right.value)
        if ok:
            return Literal(val, node.offset)  # type: ignore[arg-type]
        ok, val = _fold_comparison(node.op, left.value, right.value)
        if ok:
            return Literal(val, node.offset)  # type: ignore[arg-type]
    return BinaryOp(node.op, left, right, node.offset)


def _fold_unary_op(node: UnaryOp) -> object:
    operand = fold_constants(node.expr)
    if isinstance(operand, Literal):
        val = operand.value
        if node.op == "-" and is_num(val):
            return Literal(-val, node.offset)  # type: ignore[operator]
        if node.op == "not" and type(val) is bool:
            return Literal(not val, node.offset)
    return UnaryOp(node.op, operand, node.offset)


def fold_constants(node: object) -> object:
    if isinstance(node, ProgramNode):
        return ProgramNode(stmts=[fold_constants(s) for s in node.stmts])
    if isinstance(node, LetStmt):
        return LetStmt(node.name, fold_constants(node.expr), node.offset)
    if isinstance(node, AssignStmt):
        return AssignStmt(node.name, fold_constants(node.expr), node.offset)
    if isinstance(node, PrintStmt):
        return PrintStmt(fold_constants(node.expr), node.offset)
    if isinstance(node, IfStmt):
        tb = [fold_constants(s) for s in node.then_block]
        eb = fold_constants(node.else_branch) if node.else_branch is not None else None
        if isinstance(node.else_branch, list):
            eb = [fold_constants(s) for s in node.else_branch]
        return IfStmt(fold_constants(node.cond), tb, eb, node.offset)
    if isinstance(node, WhileStmt):
        return WhileStmt(fold_constants(node.cond), [fold_constants(s) for s in node.body], node.offset)
    if isinstance(node, BlockStmt):
        return BlockStmt([fold_constants(s) for s in node.stmts], node.offset)
    if isinstance(node, UnaryOp):
        return _fold_unary_op(node)
    if isinstance(node, BinaryOp):
        return _fold_binary_op(node)
    return node

"""Bytecode compiler for microvm."""

import dataclasses
from microvm.errors import CompileError
from microvm.opcodes import OPCODES
from microvm.optimizer import fold_constants
from microvm.parser import (
    AssignStmt,
    BinaryOp,
    BlockStmt,
    IfStmt,
    LetStmt,
    Literal,
    PrintStmt,
    ProgramNode,
    UnaryOp,
    Var,
    WhileStmt,
    parse,
)

BINARY_OP_TO_OPCODE: dict[str, str] = {
    "+": "ADD",
    "-": "SUB",
    "*": "MUL",
    "/": "DIV",
    "%": "MOD",
    "==": "EQ",
    "!=": "NE",
    "<": "LT",
    "<=": "LE",
    ">": "GT",
    ">=": "GE",
}


@dataclasses.dataclass(frozen=True)
class Instr:
    op: str            # one of OPCODES
    arg: int | None    # None exactly when the opcode takes no argument


@dataclasses.dataclass
class Program:
    constants: list        # the constant pool
    names: list[str]       # variable names, slot order = declaration order
    instructions: list     # list[Instr]


def _collect_declarations(node: object, names: list[str], seen: set[str]) -> None:
    if isinstance(node, ProgramNode):
        for stmt in node.stmts:
            _collect_declarations(stmt, names, seen)
    elif isinstance(node, BlockStmt):
        for stmt in node.stmts:
            _collect_declarations(stmt, names, seen)
    elif isinstance(node, LetStmt):
        if node.name in seen:
            raise CompileError(f"Duplicate declaration of variable '{node.name}'")
        seen.add(node.name)
        names.append(node.name)
    elif isinstance(node, IfStmt):
        for stmt in node.then_block:
            _collect_declarations(stmt, names, seen)
        if isinstance(node.else_branch, list):
            for stmt in node.else_branch:
                _collect_declarations(stmt, names, seen)
        elif isinstance(node.else_branch, IfStmt):
            _collect_declarations(node.else_branch, names, seen)
    elif isinstance(node, WhileStmt):
        for stmt in node.body:
            _collect_declarations(stmt, names, seen)


def _validate_usages(node: object, declared: set[str]) -> None:
    if isinstance(node, ProgramNode):
        for stmt in node.stmts:
            _validate_usages(stmt, declared)
    elif isinstance(node, BlockStmt):
        for stmt in node.stmts:
            _validate_usages(stmt, declared)
    elif isinstance(node, LetStmt):
        _validate_usages(node.expr, declared)
    elif isinstance(node, AssignStmt):
        if node.name not in declared:
            raise CompileError(f"Variable '{node.name}' was never declared")
        _validate_usages(node.expr, declared)
    elif isinstance(node, PrintStmt):
        _validate_usages(node.expr, declared)
    elif isinstance(node, IfStmt):
        _validate_usages(node.cond, declared)
        for stmt in node.then_block:
            _validate_usages(stmt, declared)
        if isinstance(node.else_branch, list):
            for stmt in node.else_branch:
                _validate_usages(stmt, declared)
        elif isinstance(node.else_branch, IfStmt):
            _validate_usages(node.else_branch, declared)
    elif isinstance(node, WhileStmt):
        _validate_usages(node.cond, declared)
        for stmt in node.body:
            _validate_usages(stmt, declared)
    elif isinstance(node, Var):
        if node.name not in declared:
            raise CompileError(f"Variable '{node.name}' was never declared")
    elif isinstance(node, UnaryOp):
        _validate_usages(node.expr, declared)
    elif isinstance(node, BinaryOp):
        _validate_usages(node.left, declared)
        _validate_usages(node.right, declared)


class _Compiler:
    def __init__(self, names: list[str]) -> None:
        self.names: list[str] = names
        self.slot_map: dict[str, int] = {name: i for i, name in enumerate(names)}
        self.constants: list = []
        self.const_map: dict[tuple[type, object], int] = {}
        self.instructions: list[Instr] = []

    def add_constant(self, value: object) -> int:
        key = (type(value), value)
        if key in self.const_map:
            return self.const_map[key]
        idx = len(self.constants)
        self.constants.append(value)
        self.const_map[key] = idx
        return idx

    def emit(self, op: str, arg: int | None = None) -> int:
        idx = len(self.instructions)
        self.instructions.append(Instr(op=op, arg=arg))
        return idx

    def patch(self, instr_idx: int, target: int) -> None:
        op = self.instructions[instr_idx].op
        self.instructions[instr_idx] = Instr(op=op, arg=target)

    def compile_expr(self, expr: object) -> None:
        if isinstance(expr, Literal):
            k = self.add_constant(expr.value)
            self.emit("CONST", k)
        elif isinstance(expr, Var):
            self.emit("LOAD", self.slot_map[expr.name])
        elif isinstance(expr, UnaryOp):
            self.compile_expr(expr.expr)
            self.emit("NEG" if expr.op == "-" else "NOT", None)
        elif isinstance(expr, BinaryOp):
            self.compile_binary_op(expr)

    def compile_binary_op(self, expr: BinaryOp) -> None:
        if expr.op == "and":
            self.compile_expr(expr.left)
            jf1 = self.emit("JUMP_IF_FALSE", 0)
            self.compile_expr(expr.right)
            jf2 = self.emit("JUMP_IF_FALSE", 0)
            self.emit("CONST", self.add_constant(True))
            j_end = self.emit("JUMP", 0)
            self.patch(jf1, len(self.instructions))
            self.patch(jf2, len(self.instructions))
            self.emit("CONST", self.add_constant(False))
            self.patch(j_end, len(self.instructions))
        elif expr.op == "or":
            self.compile_expr(expr.left)
            j_chk = self.emit("JUMP_IF_FALSE", 0)
            self.emit("CONST", self.add_constant(True))
            j_end1 = self.emit("JUMP", 0)
            self.patch(j_chk, len(self.instructions))
            self.compile_expr(expr.right)
            j_rf = self.emit("JUMP_IF_FALSE", 0)
            self.emit("CONST", self.add_constant(True))
            j_end2 = self.emit("JUMP", 0)
            self.patch(j_rf, len(self.instructions))
            self.emit("CONST", self.add_constant(False))
            self.patch(j_end1, len(self.instructions))
            self.patch(j_end2, len(self.instructions))
        else:
            self.compile_expr(expr.left)
            self.compile_expr(expr.right)
            self.emit(BINARY_OP_TO_OPCODE[expr.op], None)

    def compile_stmt(self, stmt: object) -> None:
        if isinstance(stmt, LetStmt):
            self.compile_expr(stmt.expr)
            self.emit("STORE", self.slot_map[stmt.name])
        elif isinstance(stmt, AssignStmt):
            self.compile_expr(stmt.expr)
            self.emit("STORE", self.slot_map[stmt.name])
        elif isinstance(stmt, PrintStmt):
            self.compile_expr(stmt.expr)
            self.emit("PRINT", None)
        elif isinstance(stmt, BlockStmt):
            for s in stmt.stmts:
                self.compile_stmt(s)
        elif isinstance(stmt, IfStmt):
            self.compile_if(stmt)
        elif isinstance(stmt, WhileStmt):
            self.compile_while(stmt)

    def compile_if(self, stmt: IfStmt) -> None:
        self.compile_expr(stmt.cond)
        jf = self.emit("JUMP_IF_FALSE", 0)
        for s in stmt.then_block:
            self.compile_stmt(s)
        if stmt.else_branch is not None:
            j_end = self.emit("JUMP", 0)
            self.patch(jf, len(self.instructions))
            if isinstance(stmt.else_branch, list):
                for s in stmt.else_branch:
                    self.compile_stmt(s)
            elif isinstance(stmt.else_branch, IfStmt):
                self.compile_stmt(stmt.else_branch)
            self.patch(j_end, len(self.instructions))
        else:
            self.patch(jf, len(self.instructions))

    def compile_while(self, stmt: WhileStmt) -> None:
        loop_start = len(self.instructions)
        self.compile_expr(stmt.cond)
        j_exit = self.emit("JUMP_IF_FALSE", 0)
        for s in stmt.body:
            self.compile_stmt(s)
        self.emit("JUMP", loop_start)
        self.patch(j_exit, len(self.instructions))


def compile_source(src: str, *, optimize: bool = False) -> Program:
    ast = parse(src)
    if optimize:
        ast = fold_constants(ast)
    names: list[str] = []
    seen: set[str] = set()
    _collect_declarations(ast, names, seen)
    _validate_usages(ast, seen)
    compiler = _Compiler(names)
    if isinstance(ast, ProgramNode):
        for stmt in ast.stmts:
            compiler.compile_stmt(stmt)
    compiler.emit("HALT", None)
    return Program(
        constants=compiler.constants,
        names=compiler.names,
        instructions=compiler.instructions,
    )

"""Stack virtual machine for microvm."""

from microvm.compiler import Program
from microvm.errors import StepLimitError, VMRuntimeError
from microvm.optimizer import is_num, vm_equals

_UNSET: object = object()


def _format_print_value(val: object) -> str:
    if type(val) is bool:
        return "true" if val else "false"
    if type(val) is int or type(val) is float:
        return str(val)
    if type(val) is str:
        return val
    return str(val)


def _exec_arithmetic(op: str, left: object, right: object) -> object:
    if op == "ADD":
        if type(left) is str and type(right) is str:
            return left + right
        if is_num(left) and is_num(right):
            res = left + right  # type: ignore[operator]
            return int(res) if (type(left) is int and type(right) is int) else float(res)
        raise VMRuntimeError("Operands to '+' must be two numbers or two strings")
    if op in ("SUB", "MUL"):
        if is_num(left) and is_num(right):
            res = (left - right) if op == "SUB" else (left * right)  # type: ignore[operator]
            return int(res) if (type(left) is int and type(right) is int) else float(res)
        raise VMRuntimeError(f"Operands to '{op}' must be numbers")
    if op == "DIV":
        if is_num(left) and is_num(right):
            if right == 0:
                raise VMRuntimeError("Division by zero")
            return float(left) / float(right)  # type: ignore[arg-type]
        raise VMRuntimeError("Operands to '/' must be numbers")
    if op == "MOD":
        if type(left) is int and type(right) is int and type(left) is not bool and type(right) is not bool:
            if right == 0:
                raise VMRuntimeError("Modulo by zero")
            return left % right
        raise VMRuntimeError("Operands to '%' must be integers")
    raise VMRuntimeError(f"Unknown arithmetic opcode {op}")


def _exec_comparison(op: str, left: object, right: object) -> bool:
    if op == "EQ":
        return vm_equals(left, right)
    if op == "NE":
        return not vm_equals(left, right)
    if is_num(left) and is_num(right):
        if op == "LT":
            return left < right  # type: ignore[operator]
        if op == "LE":
            return left <= right  # type: ignore[operator]
        if op == "GT":
            return left > right  # type: ignore[operator]
        if op == "GE":
            return left >= right  # type: ignore[operator]
    if type(left) is str and type(right) is str:
        if op == "LT":
            return left < right
        if op == "LE":
            return left <= right
        if op == "GT":
            return left > right
        if op == "GE":
            return left >= right
    raise VMRuntimeError(f"Invalid operands for comparison {op}")


def _dispatch_instr(
    op: str,
    arg: int | None,
    stack: list[object],
    slots: list[object],
    program: Program,
    output: list[str],
    pc: int,
) -> int:
    if op == "CONST":
        stack.append(program.constants[arg])  # type: ignore[index]
        return pc + 1
    if op == "LOAD":
        val = slots[arg]  # type: ignore[index]
        if val is _UNSET:
            raise VMRuntimeError(f"Variable '{program.names[arg]}' was never assigned")  # type: ignore[index]
        stack.append(val)
        return pc + 1
    if op == "STORE":
        slots[arg] = stack.pop()  # type: ignore[index]
        return pc + 1
    if op in ("ADD", "SUB", "MUL", "DIV", "MOD"):
        right = stack.pop()
        left = stack.pop()
        stack.append(_exec_arithmetic(op, left, right))
        return pc + 1
    if op in ("EQ", "NE", "LT", "LE", "GT", "GE"):
        right = stack.pop()
        left = stack.pop()
        stack.append(_exec_comparison(op, left, right))
        return pc + 1
    if op == "NEG":
        val = stack.pop()
        if not is_num(val):
            raise VMRuntimeError("Unary '-' requires a number")
        stack.append(-val)  # type: ignore[operator]
        return pc + 1
    if op == "NOT":
        val = stack.pop()
        if type(val) is not bool:
            raise VMRuntimeError("'not' requires a bool")
        stack.append(not val)
        return pc + 1
    if op == "PRINT":
        output.append(_format_print_value(stack.pop()))
        return pc + 1
    if op == "POP":
        stack.pop()
        return pc + 1
    if op == "JUMP":
        return arg  # type: ignore[return-value]
    if op == "JUMP_IF_FALSE":
        cond = stack.pop()
        if type(cond) is not bool:
            raise VMRuntimeError("JUMP_IF_FALSE condition must be a bool")
        return arg if not cond else (pc + 1)  # type: ignore[return-value]
    raise VMRuntimeError(f"Unknown opcode {op}")


def execute(program: Program, *, step_limit: int = 100_000) -> list[str]:
    if type(step_limit) is not int or step_limit <= 0:
        raise ValueError("step_limit must be a positive int")
    slots: list[object] = [_UNSET] * len(program.names)
    stack: list[object] = []
    output: list[str] = []
    pc = 0
    steps = 0
    num_instructions = len(program.instructions)
    while pc < num_instructions:
        steps += 1
        if steps > step_limit:
            raise StepLimitError("Execution exceeded step limit")
        instr = program.instructions[pc]
        if instr.op == "HALT":
            break
        pc = _dispatch_instr(instr.op, instr.arg, stack, slots, program, output, pc)
    return output

"""Binary serialization and deserialization for microvm programs."""

import struct
import zlib
from microvm.compiler import Instr, Program
from microvm.errors import SerializationError
from microvm.opcodes import OPCODE_NUMBERS, OPCODES

MAGIC: bytes = b"MVM1"
ARG_OPCODES: frozenset[str] = frozenset({"CONST", "LOAD", "STORE", "JUMP", "JUMP_IF_FALSE"})
NO_ARG: int = 0xFFFFFFFF


def _encode_constant(c: object) -> bytes:
    if type(c) is bool:
        return b"\x04" + (b"\x01" if c else b"\x00")
    if type(c) is int:
        if not (-9223372036854775808 <= c <= 9223372036854775807):
            raise SerializationError(f"Integer constant {c} out of 64-bit signed range")
        return b"\x01" + struct.pack(">q", c)
    if type(c) is float:
        return b"\x02" + struct.pack(">d", c)
    if type(c) is str:
        data = c.encode("utf-8")
        if len(data) > NO_ARG:
            raise SerializationError("String constant too long")
        return b"\x03" + struct.pack(">I", len(data)) + data
    raise SerializationError(f"Unknown constant type {type(c)}")


def _encode_instruction(instr: Instr) -> bytes:
    if instr.op not in OPCODE_NUMBERS:
        raise SerializationError(f"Unknown opcode '{instr.op}'")
    op_num = OPCODE_NUMBERS[instr.op]
    if instr.op in ARG_OPCODES:
        if instr.arg is None or not (0 <= instr.arg < NO_ARG):
            raise SerializationError(f"Opcode '{instr.op}' requires valid argument")
        arg = instr.arg
    else:
        if instr.arg is not None:
            raise SerializationError(f"Opcode '{instr.op}' cannot have argument")
        arg = NO_ARG
    return struct.pack(">BI", op_num, arg)


def dumps(program: Program) -> bytes:
    parts: list[bytes] = [b"\x01"]
    if len(program.names) > 0xFFFF:
        raise SerializationError("Too many names")
    parts.append(struct.pack(">H", len(program.names)))
    for name in program.names:
        encoded = name.encode("utf-8")
        if len(encoded) > 0xFFFF:
            raise SerializationError(f"Name '{name}' too long")
        parts.append(struct.pack(">H", len(encoded)) + encoded)
    if len(program.constants) > 0xFFFF:
        raise SerializationError("Too many constants")
    parts.append(struct.pack(">H", len(program.constants)))
    for c in program.constants:
        parts.append(_encode_constant(c))
    if len(program.instructions) > NO_ARG:
        raise SerializationError("Too many instructions")
    parts.append(struct.pack(">I", len(program.instructions)))
    for instr in program.instructions:
        parts.append(_encode_instruction(instr))
    body = b"".join(parts)
    crc = zlib.crc32(body) & 0xFFFFFFFF
    return MAGIC + body + struct.pack(">I", crc)


def _decode_names(data: bytes, pos: int, end: int) -> tuple[list[str], int]:
    if pos + 2 > end:
        raise SerializationError("Truncated data in name count")
    (name_count,) = struct.unpack(">H", data[pos : pos + 2])
    pos += 2
    names: list[str] = []
    for _ in range(name_count):
        if pos + 2 > end:
            raise SerializationError("Truncated name length")
        (nlen,) = struct.unpack(">H", data[pos : pos + 2])
        pos += 2
        if pos + nlen > end:
            raise SerializationError("Truncated name bytes")
        try:
            names.append(data[pos : pos + nlen].decode("utf-8"))
        except UnicodeDecodeError as exc:
            raise SerializationError("Invalid UTF-8 in name") from exc
        pos += nlen
    return names, pos


def _decode_constants(data: bytes, pos: int, end: int) -> tuple[list[object], int]:
    if pos + 2 > end:
        raise SerializationError("Truncated data in constant count")
    (const_count,) = struct.unpack(">H", data[pos : pos + 2])
    pos += 2
    constants: list[object] = []
    for _ in range(const_count):
        if pos + 1 > end:
            raise SerializationError("Truncated constant tag")
        tag = data[pos]
        pos += 1
        if tag == 1:
            if pos + 8 > end:
                raise SerializationError("Truncated INT constant")
            constants.append(struct.unpack(">q", data[pos : pos + 8])[0])
            pos += 8
        elif tag == 2:
            if pos + 8 > end:
                raise SerializationError("Truncated FLOAT constant")
            constants.append(struct.unpack(">d", data[pos : pos + 8])[0])
            pos += 8
        elif tag == 3:
            if pos + 4 > end:
                raise SerializationError("Truncated STRING length")
            (slen,) = struct.unpack(">I", data[pos : pos + 4])
            pos += 4
            if pos + slen > end:
                raise SerializationError("Truncated STRING bytes")
            try:
                constants.append(data[pos : pos + slen].decode("utf-8"))
            except UnicodeDecodeError as exc:
                raise SerializationError("Invalid UTF-8 in string constant") from exc
            pos += slen
        elif tag == 4:
            if pos + 1 > end:
                raise SerializationError("Truncated BOOL constant")
            bval = data[pos]
            pos += 1
            if bval not in (0, 1):
                raise SerializationError(f"Invalid BOOL constant value {bval}")
            constants.append(bool(bval))
        else:
            raise SerializationError(f"Unknown constant tag {tag}")
    return constants, pos


def _decode_instructions(data: bytes, pos: int, end: int) -> tuple[list[Instr], int]:
    if pos + 4 > end:
        raise SerializationError("Truncated instruction count")
    (instr_count,) = struct.unpack(">I", data[pos : pos + 4])
    pos += 4
    instructions: list[Instr] = []
    for _ in range(instr_count):
        if pos + 5 > end:
            raise SerializationError("Truncated instruction")
        op_num, arg_raw = struct.unpack(">BI", data[pos : pos + 5])
        pos += 5
        if not (1 <= op_num <= len(OPCODES)):
            raise SerializationError(f"Unknown opcode number {op_num}")
        op_name = OPCODES[op_num - 1]
        if op_name in ARG_OPCODES:
            if arg_raw == NO_ARG:
                raise SerializationError(f"Opcode '{op_name}' requires an argument")
            instructions.append(Instr(op=op_name, arg=arg_raw))
        else:
            if arg_raw != NO_ARG:
                raise SerializationError(f"Opcode '{op_name}' cannot have an argument")
            instructions.append(Instr(op=op_name, arg=None))
    return instructions, pos


def loads(data: bytes) -> Program:
    if len(data) < 17:
        raise SerializationError("Data too short to be valid microvm binary")
    if data[:4] != MAGIC:
        raise SerializationError("Invalid magic header")
    (expected_crc,) = struct.unpack(">I", data[-4:])
    actual_crc = zlib.crc32(data[4:-4]) & 0xFFFFFFFF
    if expected_crc != actual_crc:
        raise SerializationError("CRC32 checksum mismatch")
    if data[4] != 1:
        raise SerializationError(f"Unsupported binary version {data[4]}")
    pos = 5
    end = len(data) - 4
    names, pos = _decode_names(data, pos, end)
    constants, pos = _decode_constants(data, pos, end)
    instructions, pos = _decode_instructions(data, pos, end)
    if pos != end:
        raise SerializationError("Trailing bytes before checksum")
    return Program(constants=constants, names=names, instructions=instructions)

"""Disassembler for microvm programs."""

from microvm.compiler import Program


def _format_constant(c: object) -> str:
    if type(c) is bool:
        return "true" if c else "false"
    if type(c) is int or type(c) is float:
        return str(c)
    if type(c) is str:
        chars: list[str] = []
        for ch in c:
            if ch == "\\":
                chars.append("\\\\")
            elif ch == '"':
                chars.append('\\"')
            elif ch == "\n":
                chars.append("\\n")
            elif ch == "\t":
                chars.append("\\t")
            else:
                chars.append(ch)
        return '"' + "".join(chars) + '"'
    return str(c)


def disassemble(program: Program) -> str:
    lines: list[str] = []
    for index, instr in enumerate(program.instructions):
        if instr.op == "CONST":
            rendered = _format_constant(program.constants[instr.arg])  # type: ignore[index]
            lines.append(f"{index:04d} CONST {instr.arg}  ; {rendered}\n")
        elif instr.arg is not None:
            lines.append(f"{index:04d} {instr.op} {instr.arg}\n")
        else:
            lines.append(f"{index:04d} {instr.op}\n")
    return "".join(lines)

"""Command-line interface for microvm."""

import argparse
import sys
from microvm.compiler import compile_source
from microvm.disassembler import disassemble
from microvm.errors import MicroVMError
from microvm.serializer import dumps, loads
from microvm.vm import execute


class UsageError(Exception):
    """Command-line usage error."""


class _CustomParser(argparse.ArgumentParser):
    def error(self, message: str) -> None:
        raise UsageError(message)


def _build_parser() -> _CustomParser:
    parser = _CustomParser(prog="microvm")
    subparsers = parser.add_subparsers(dest="command", required=True)

    run_p = subparsers.add_parser("run")
    run_p.add_argument("file", help="Source file path")
    run_p.add_argument("--optimize", action="store_true", help="Enable constant folding")
    run_p.add_argument("--step-limit", type=int, default=100_000, help="Step execution limit")

    build_p = subparsers.add_parser("build")
    build_p.add_argument("file", help="Source file path")
    build_p.add_argument("out", help="Output binary file path")
    build_p.add_argument("--optimize", action="store_true", help="Enable constant folding")

    exec_p = subparsers.add_parser("exec")
    exec_p.add_argument("file", help="Binary file path")
    exec_p.add_argument("--step-limit", type=int, default=100_000, help="Step execution limit")

    disasm_p = subparsers.add_parser("disasm")
    disasm_p.add_argument("file", help="Binary file path")

    return parser


def _cmd_run(args: argparse.Namespace) -> int:
    if args.step_limit <= 0:
        raise UsageError("--step-limit must be a positive integer")
    try:
        with open(args.file, "r", encoding="utf-8") as f:
            src = f.read()
    except OSError as exc:
        raise UsageError(f"Cannot read file '{args.file}': {exc}") from exc
    prog = compile_source(src, optimize=args.optimize)
    output = execute(prog, step_limit=args.step_limit)
    for line in output:
        sys.stdout.write(line + "\n")
    return 0


def _cmd_build(args: argparse.Namespace) -> int:
    try:
        with open(args.file, "r", encoding="utf-8") as f:
            src = f.read()
    except OSError as exc:
        raise UsageError(f"Cannot read file '{args.file}': {exc}") from exc
    prog = compile_source(src, optimize=args.optimize)
    data = dumps(prog)
    try:
        with open(args.out, "wb") as f:
            f.write(data)
    except OSError as exc:
        raise UsageError(f"Cannot write file '{args.out}': {exc}") from exc
    return 0


def _cmd_exec(args: argparse.Namespace) -> int:
    if args.step_limit <= 0:
        raise UsageError("--step-limit must be a positive integer")
    try:
        with open(args.file, "rb") as f:
            data = f.read()
    except OSError as exc:
        raise UsageError(f"Cannot read file '{args.file}': {exc}") from exc
    prog = loads(data)
    output = execute(prog, step_limit=args.step_limit)
    for line in output:
        sys.stdout.write(line + "\n")
    return 0


def _cmd_disasm(args: argparse.Namespace) -> int:
    try:
        with open(args.file, "rb") as f:
            data = f.read()
    except OSError as exc:
        raise UsageError(f"Cannot read file '{args.file}': {exc}") from exc
    prog = loads(data)
    text = disassemble(prog)
    sys.stdout.write(text)
    return 0


def main(argv: list[str] | None = None) -> int:
    if argv is None:
        argv = sys.argv[1:]
    parser = _build_parser()
    try:
        args = parser.parse_args(argv)
        if args.command == "run":
            return _cmd_run(args)
        if args.command == "build":
            return _cmd_build(args)
        if args.command == "exec":
            return _cmd_exec(args)
        if args.command == "disasm":
            return _cmd_disasm(args)
        raise UsageError(f"Unknown command {args.command}")
    except UsageError as exc:
        sys.stderr.write(f"Usage error: {exc}\n")
        return 2
    except MicroVMError as exc:
        sys.stderr.write(f"Error: {exc}\n")
        return 3


if __name__ == "__main__":
    sys.exit(main())

